import React from 'react';

const Programs = () => {
  return (
    <div className="programs-page">
      {/* Hero Section */}
      <section className="programs-hero">
        <div className="hero-container">
          <div className="hero-content">
            <h1>Our Programs</h1>
            <p>Comprehensive support systems designed to nurture, educate, and empower children to reach their full potential. From early childhood development to vocational training, we provide the foundation for lifelong success.</p>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Programs;
